def strip_prefix(name, prefix):
    """Return `name` without the leading `prefix`.

    When `name` does not actually start with `prefix` it is returned unchanged, and
    an empty prefix is a no-op.
    """
    if not prefix:
        return name
    return name[len(prefix) :]


